-- P3 source/landing columns (11 object from raw SQL) (2026-10-28T15:26:53) - run on Oracle Dev
-- single SELECT: run with Ctrl+Enter, export result as CSV (with header) into input/run_results/<this pack name>/
SELECT c.owner, c.table_name, c.column_id, c.column_name, c.data_type, c.data_length, c.data_precision, c.data_scale, c.nullable
FROM all_tab_columns c WHERE c.table_name IN (SELECT column_value FROM TABLE(sys.odcivarchar2list('EXT_DSS_CHECKPOINT_TB_TRANSACTION_SS_ESIM_VALID', 'EXT_DSS_TB_MASTER_CDR_TYPE', 'EXT_DSS_VW_SERVICE_MAPPING_BNO_KEY', 'TB_LANDING_SS_ESIM', 'TB_STAGING_SS_ESIM_CHECKPOINT', 'TB_STAGING_SS_ESIM_CHECKPOINT_TEMP', 'TB_STAGING_SS_ESIM_LANDING_TO_DISCOVERY_WORKFLOW_STATUS', 'TB_STAGING_SS_ESIM_RAW_TEMP', 'TB_TRANSACTION_SS_ESIM_REJECT', 'TB_TRANSACTION_SS_ESIM_TEMP', 'TB_TRANSACTION_SS_ESIM_VALID')))
UNION ALL
SELECT NULL, t.column_value, NULL, 'MISSING_OBJECT', NULL, NULL, NULL, NULL, NULL
FROM TABLE(sys.odcivarchar2list('EXT_DSS_CHECKPOINT_TB_TRANSACTION_SS_ESIM_VALID', 'EXT_DSS_TB_MASTER_CDR_TYPE', 'EXT_DSS_VW_SERVICE_MAPPING_BNO_KEY', 'TB_LANDING_SS_ESIM', 'TB_STAGING_SS_ESIM_CHECKPOINT', 'TB_STAGING_SS_ESIM_CHECKPOINT_TEMP', 'TB_STAGING_SS_ESIM_LANDING_TO_DISCOVERY_WORKFLOW_STATUS', 'TB_STAGING_SS_ESIM_RAW_TEMP', 'TB_TRANSACTION_SS_ESIM_REJECT', 'TB_TRANSACTION_SS_ESIM_TEMP', 'TB_TRANSACTION_SS_ESIM_VALID')) t WHERE NOT EXISTS (SELECT 1 FROM all_tab_columns a WHERE a.table_name = t.column_value)
ORDER BY 2, 1, 3
